import sys

def main():
    data = sys.stdin.read().split()
    s, t = data[0], data[1]
    n = len(s)
    order = data[2:2 + n]
    when = [0] * n
    for step in range(n):
        when[int(order[step]) - 1] = step
    m = len(t)

    def ok(k):
        j = 0
        for i in range(n):
            if when[i] >= k and s[i] == t[j]:
                j += 1
                if j == m:
                    return True
        return False

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

